{
  "summary": "Test the intermittent rearview camera outage on a 2021 Polestar 2 by running the rulebook's long-run power cycling test, because the camera delays, stutters, flickers, and becomes temporarily unavailable when reverse is selected.",
  "rationale": "The narrative reports that the backup camera is unreliable and that, often upon selecting reverse, the display is delayed, then stutters and flickers before showing \"Camera is temporarily unavailable.\" The intake extraction marks the condition as intermittent, which matches the rulebook entry for intermittent faults and supports a targeted long-run power cycling test.",
  "group": "adas",
  "symptoms": [
    "backup camera unreliable",
    "delayed camera view when selecting reverse",
    "camera view stutters and flickers",
    "Camera is temporarily unavailable"
  ],
  "conditions": [
    "selecting reverse",
    "intermittent"
  ],
  "fault_codes": [],
  "safety_relevant": false,
  "targeted": true,
  "test_name": "Long-run power cycling test",
  "clues": [
    {
      "kind": "symptom",
      "quote": "The backup camera on this vehicle is very unreliable."
    },
    {
      "kind": "condition",
      "quote": "Often upon selecting reverse"
    },
    {
      "kind": "symptom",
      "quote": "take too long to display the camera view"
    },
    {
      "kind": "symptom",
      "quote": "stutter and flicker"
    },
    {
      "kind": "symptom",
      "quote": "Camera is temporarily unavailable"
    },
    {
      "kind": "component_group",
      "quote": "backup camera"
    },
    {
      "kind": "other",
      "quote": "recalled by the Polestar for this issue (25V-280)"
    }
  ]
}

